const fs = require('fs');
const path = require('path');

const katolikQuestions = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'generators', 'agama_katolik.json'), 'utf8'));
const seenQuestions = new Set(katolikQuestions.map(q => q.question));

function addQ(grade, difficulty, topic, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate Katolik question found: "${question}"`);
  }
  seenQuestions.add(question);

  const diffCode = difficulty === 'mudah' ? 'm' : (difficulty === 'sedang' ? 's' : 'u');
  const index = katolikQuestions.filter(q => q.grade === grade && q.difficulty === difficulty).length + 1;
  const id = `aga-katolik-k${grade}-${diffCode}${String(index).padStart(2, '0')}`;

  katolikQuestions.push({
    id,
    grade,
    subject: 'pendidikan-agama',
    religion: 'katolik',
    difficulty,
    topic,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ(2, 'mudah', 'Sakramen Baptis', 'Sakramen inisiasi pertama yang kita terima untuk menghapus dosa asal dan menjadikan kita anggota Gereja Katolik adalah Sakramen ...', ['Ekaristi', 'Baptis', 'Krisma', 'Tobat'], 1, 'Sakramen Baptis adalah pintu gerbang menuju sakramen-sakramen lainnya dan melahirkan kita kembali menjadi anak Allah.');
addQ(2, 'mudah', 'Materi Baptis', 'Materi atau benda suci yang dituangkan tiga kali ke atas dahi calon baptis sambil menyebut nama Bapa, Putra, dan Roh Kudus adalah ...', ['Minyak goreng', 'Air suci baptis', 'Air anggur', 'Susu murni'], 1, 'Air suci yang dituangkan melambangkan pembersihan batin dan kelahiran baru dalam Kristus.');
addQ(2, 'mudah', 'Kain Putih Baptis', 'Pakaian putih yang dikenakan pada bayi atau anak saat dibaptis melambangkan ...', ['Kekayaan orang tua', 'Kesucian hidup baru yang telah dibersihkan dari dosa dan mengenakan Kristus', 'Tradisi pakaian pesta di Eropa', 'Warna seragam sekolah minggu'], 1, 'Kain putih melambangkan kemurnian hidup baru yang harus dijaga tanpa noda hingga menghadap pengadilan Kristus.');
addQ(2, 'mudah', 'Imam Katolik', 'Pemimpin perayaan Ekaristi (Misa Kudus) dan pelayan sakramen dalam Gereja Katolik adalah seorang ...', ['Biarawati (Suster)', 'Imam (Pastor / Romo)', 'Bruder', 'Misdinar'], 1, 'Imam ditahbiskan untuk bertindak dalam pribadi Kristus (in persona Christi) memimpin Ekaristi.');
addQ(2, 'mudah', 'Santo Yosef', 'Ayah asuh Tuhan Yesus di bumi yang mendampingi Bunda Maria dan berprofesi sebagai tukang kayu di Nazaret adalah Santo ...', ['Petrus', 'Yosef', 'Yohanes', 'Yakobus'], 1, 'Santo Yosef adalah bapa yang setia, tulus hati, dan pelindung Keluarga Kudus.');
addQ(2, 'mudah', 'Yesus dan Anak', 'Tuhan Yesus sangat mengasihi anak-anak dan bersabda: "Biarkanlah anak-anak itu datang kepada-Ku, sebab merekalah yang empunya ..."', ['Harta dunia', 'Kerajaan Surga', 'Istana kaisar', 'Seluruh pasukan tentara'], 1, 'Matius 19:14: Yesus menyambut anak-anak sebagai teladan kemurnian bagi pemilik Kerajaan Surga.');
addQ(2, 'mudah', 'Doa Pengampunan', 'Doa yang kita panjatkan untuk memohon pengampunan atas segala kesalahan dan dosa kita kepada Allah yang mahabaik adalah Doa ...', ['Tobat', 'Angelus', 'Rosario', 'Makan'], 0, 'Doa Tobat mengungkapkan penyesalan batin dan kerinduan beroleh kerahiman Allah.');
addQ(2, 'mudah', 'Putra Altar', 'Anak-anak yang bertugas membantu imam di sekitar altar selama perayaan Ekaristi kudus disebut ...', ['Lektor pembaca sabda', 'Misdinar (Putra-Putri Altar)', 'Dirigen paduan suara', 'Kolektan penarik persembahan'], 1, 'Misdinar bertugas melayani altar demi kelancaran dan kekhidmatan liturgi.');
addQ(2, 'mudah', 'Lampu Tabernakel', 'Lampu berwarna merah yang menyala di dekat Tabernakel menandakan bahwa di dalam Tabernakel bertahta ...', ['Malaikat penjaga', 'Sakramen Mahakudus (Tubuh Kristus)', 'Buku puji syukur', 'Minyak wangi gereja'], 1, 'Lampu Abadi (Sanctuary Lamp) berwarna merah menandakan kehadiran nyata Kristus dalam Ekaristi.');
addQ(2, 'mudah', 'Misa Hari Minggu', 'Hari Minggu merupakan hari raya mingguan kebangkitan Kristus di mana seluruh umat Katolik diwajibkan menghadiri ...', ['Rapat pengurus RT', 'Perayaan Ekaristi (Misa Kudus)', 'Pesta olahraga kota', 'Kerja bakti kampung'], 1, 'Misa hari Minggu adalah kewajiban persekutuan jemaat memperingati kebangkitan Tuhan.');

addQ(2, 'sedang', 'Salam Damai Liturgi', 'Pemberian salam damai sebelum komuni dalam Misa kudus mengingatkan kita untuk selalu hidup ...', ['Saling bersaing ketat', 'Rukun, damai, dan saling mengasihi dengan sesama', 'Menang sendiri dalam perdebatan', 'Menjauhi orang yang berbeda pendapat'], 1, 'Salam damai menegaskan bahwa persekutuan dengan Kristus menuntut perdamaian dengan sesama.');
addQ(2, 'sedang', 'Keteladanan Yosef Bekerja', 'Santo Yosef bekerja keras mencari nafkah sebagai tukang kayu di Nazaret dengan jujur dan tekun. Teladan moral yang dapat kita tiru adalah ...', ['Mencari uang dengan cara curang', 'Menghargai kerja keras, rajin belajar, dan tidak bermalas-malasan', 'Menuntut orang tua selalu memberi uang jajan', 'Menghindari pekerjaan rumah tangga'], 1, 'Santo Yosef menguduskan pekerjaan harian melalui ketekunan dan kejujuran hidup.');
addQ(2, 'sedang', 'Pertolongan Sesama di Sekolah', 'Ketika melihat teman sebangku terjatuh dan lututnya berdarah di lapangan sekolah, tindakan anak beriman katolik adalah ...', ['Menertawakan kecerobohannya', 'Segera menolongnya berdiri, membantunya ke ruang UKS, dan memberitahu bapak guru', 'Meninggalkannya begitu saja agar tidak terlambat masuk kelas', 'Menuduhnya sedang berpura-pura sakit'], 1, 'Tindakan empati dan pertolongan pertama adalah wujud nyata kasih sesama.');
addQ(2, 'sedang', 'Sikap Hormat di Kapel', 'Perilaku yang benar saat berada di dalam ruang kapel sekolah adalah ...', ['Berlari-larian mengejar kawan', 'Duduk tenang, bersikap sopan, dan berdoa dengan khidmat', 'Makan camilan biskuit di bawah bangku', 'Bercanda tertawa terbahak-bahak'], 1, 'Menjaga ketenangan di rumah Tuhan mencerminkan rasa hormat dan kesiapan hati berdoa.');
addQ(2, 'sedang', 'Persembahan Para Majus', 'Tiga orang Majus mempersembahkan hadiah istimewa kepada bayi Yesus berupa emas, kemenyan, dan ...', ['Intan permata berkilau', 'Mur (minyak wangi mur)', 'Kain sutera ungu', 'Gandum terbaik'], 1, 'Mur melambangkan pengurapan penguburan dan pengorbanan wafat Kristus.');
addQ(2, 'sedang', 'Iman Kawan yang Lumpuh', 'Yesus menyembuhkan orang lumpuh yang diturunkan dari atap rumah oleh empat kawannya karena Yesus melihat ...', ['Kekayaan emas yang dibawa kawan-kawannya', 'Besarnya iman dan kasih persahabatan mereka yang pantang menyerah', 'Kekuatan fisik mereka membongkar atap', 'Surat rekomendasi dari kepala rumah ibadat'], 1, 'Markus 2:5: Yesus melihat iman kawan-kawan yang teguh memperjuangkan kesembuhan sahabatnya.');
addQ(2, 'sedang', 'Hormat Guru Sekolah Katolik', 'Menghormati bapak dan ibu guru di sekolah Katolik dicontohkan dengan ...', ['Mencemooh guru saat di luar kelas', 'Mendengarkan penjelasan materi dengan saksama dan mengerjakan tugas sekolah dengan jujur', 'Mengabaikan instruksi guru piket', 'Berbicara sendiri saat guru menerangkan'], 1, 'Menghormati guru adalah bentuk penghargaan terhadap figur pendidik utusan Tuhan.');
addQ(2, 'sedang', 'Syahadat Para Rasul', 'Doa "Aku Percaya" (Kredo Para Rasul) berisi ringkasan pokok-pokok ...', ['Cerita legenda rakyat kuno', 'Iman kepercayaan Gereja Katolik kepada Allah Bapa, Putra, dan Roh Kudus', 'Hukum pidana negara', 'Aturan bermain sepak bola'], 1, 'Syahadat Para Rasul adalah pengakuan iman gerejawi warisan para rasul sejak abad perdana.');
addQ(2, 'sedang', 'Doa Bapa Kami Pengampunan', 'Kalimat Doa Bapa Kami yang mengajarkan kita untuk tidak menyimpan dendam kepada teman berbunyi: ...', ['"Jadilah kehendak-Mu di bumi seperti di surga"', '"Ampunilah kesalahan kami, seperti kami pun mengampuni yang bersalah kepada kami"', '"Berikanlah kami pada hari ini makanan kami yang secukupnya"', '"Janganlah masukkan kami ke dalam pencobaan"'], 1, 'Syarat menerima pengampunan Bapa adalah kerelaan hati memaafkan kesalahan sesama.');
addQ(2, 'sedang', 'Kerukunan Rumah Tangga', 'Salah satu cara menciptakan kerukunan antara adik dan kakak di rumah adalah ...', ['Berebut mainan hingga salah satu menangis', 'Saling berbagi mainan, saling mengalah, dan saling menolong dengan penuh kasih', 'Menyalahkan adik setiap kali ada barang pecah', 'Mengejek kegagalan kakak saat ulangan'], 1, 'Kerukunan persaudaraan di rumah mendatangkan damai dan sukacita dalam keluarga.');
addQ(2, 'sedang', 'Makna Genufleksi', 'Berlutut sejenak dengan lutut kanan menyentuh lantai (genufleksi) saat menghadap Tabernakel adalah ungkapan ...', ['Rasa kantuk karena lelah berjalan', 'Penyembahan dan hormat takwa kepada Tuhan Yesus yang hadir dalam Ekaristi Mahakudus', 'Senam peregangan kaki', 'Permintaan izin duduk kepada petugas keamanan gereja'], 1, 'Genufleksi adalah tanda kerendahan hati menyembah Sang Raja Semesta Alam.');
addQ(2, 'sedang', 'Lilin Perarakan Misdinar', 'Misdinar yang membawa lilin bernyala mendampingi imam dalam perarakan masuk Misa melambangkan bahwa Kristus adalah ...', ['Pahlawan perang berkuda', 'Terang sejati yang menghalau kegelapan dosa dunia', 'Penguasa api padang pasir', 'Tanda bahwa hari sudah malam'], 1, 'Lilin perarakan liturgis melambangkan Terang Kristus yang menuntun langkah hidup manusia.');
addQ(2, 'sedang', 'Mukjizat di Kana', 'Mukjizat pertama yang dilakukan oleh Tuhan Yesus atas permohonan Bunda Maria adalah mengubah air menjadi anggur pada pesta pernikahan di kota ...', ['Nazaret', 'Kana di Galilea', 'Yerusalem', 'Kafarnaum'], 1, 'Yohanes 2 mencatat mukjizat pertama Yesus menyatakan kemuliaan-Nya di perkawinan Kana.');
addQ(2, 'sedang', 'Pesan Bunda Maria di Kana', 'Pesan abadi Bunda Maria kepada para pelayan pesta perkawinan di Kana yang menjadi pedoman hidup kita adalah: ...', ['"Minumlah anggur itu sampai habis"', '"Apa yang dikatakan-Nya kepadamu, buatlah itu!"', '"Pulanglah ke rumah masing-masing"', '"Mintalah uang ganti rugi kepada pengantin"'], 1, 'Bunda Maria selalu menuntun umat manusia untuk taat dan melakukan segala perintah putranya, Yesus.');
addQ(2, 'sedang', 'Panggilan Laudato Si\' di Rumah', 'Tindakan seorang anak katolik di rumah yang mencerminkan semangat merawat bumi (Laudato Si\') adalah ...', ['Membiarkan lampu kamar menyala sepanjang siang hari', 'Mematikan lampu saat tidak digunakan dan tidak membuang-buang air bersih saat mandi', 'Membuang baterai bekas ke dalam saluran air got', 'Mencabut tanaman hias ibu hingga layu'], 1, 'Hemat energi dan air merupakan aksi nyata pertobatan ekologis anak beriman.');
addQ(2, 'sedang', 'Persahabatan Lintas Agama', 'Bila di lingkungan rumah tetangga kita beragama lain sedang merayakan hari rayanya, sikap anak katolik yang baik adalah ...', ['Melemparkan batu ke arah rumahnya', 'Memberikan ucapan selamat dengan ramah dan ikut menjaga ketenangan lingkungan', 'Melarang mereka keluar rumah', 'Memusuhi teman yang berbeda agama'], 1, 'Persaudaraan insani menuntut sikap saling menghormati dan menjaga kerukunan hidup bersama.');
addQ(2, 'sedang', 'Santo Yosef Sang Pelindung', 'Gereja Katolik menghormati Santo Yosef dengan menganugerahinya gelar istimewa yaitu Pelindung ...', ['Para pedagang senjata', 'Gereja Semesta dan Kaum Pekerja', 'Para atlet maraton', 'Kaisar-kaisar Eropa'], 1, 'Paus Pius IX menetapkan Santo Yosef sebagai Pelindung Gereja Semesta.');
addQ(2, 'sedang', 'Doa Rosario Berkeluarga', 'Untaian manik-manik yang digunakan oleh umat Katolik saat berdoa Salam Maria berulang-ulang untuk merenungkan peristiwa hidup Yesus dinamakan ...', ['Tasbih biasa', 'Kalung Rosario', 'Rantai perhiasan emas', 'Tali pengikat buku'], 1, 'Doa Rosario adalah doa kontemplatif merenungkan misteri keselamatan Kristus bersama Bunda Maria.');
addQ(2, 'sedang', 'Menolong Orang Lanjut Usia', 'Membantu kakek atau nenek menyeberang jalan atau membawakan barang bawaannya yang berat merupakan cerminan pengamalan ...', ['Perilaku mencari pujian lurah', 'Cinta kasih kristiani dan penghormatan kepada orang tua', 'Beban tugas sekolah yang memberatkan', 'Hukuman dari guru kelas'], 1, 'Menghormati dan menolong kaum lansia adalah perintah kasih Tuhan yang luhur.');
addQ(2, 'sedang', 'Mengakui Kesalahan Segera', 'Bila kita tidak sengaja menumpahkan cat air di meja gambar teman, sikap anak katolik yang berkarakter jujur adalah ...', ['Menyalahkan teman yang duduk di depan', 'Segera meminta maaf dengan tulus, membersihkan tumpahan cat, dan membantu membetulkan gambarnya', 'Melarikan diri ke luar gerbang sekolah', 'Menangis agar tidak dimarahi guru'], 1, 'Keberanian mengakui kesalahan dan bertanggung jawab membuktikan kematangan budi pekerti.');

addQ(2, 'sulit', 'Tafsir Sabda Yesus Tentang Anak-anak', 'Yesus bersabda: "Aku berkata kepadamu: Jika kamu tidak bertobat dan menjadi seperti anak kecil ini, kamu tidak akan masuk ke dalam Kerajaan Surga". Sifat anak kecil manakah yang dipuji oleh Yesus?', ['Suka merajuk dan menangis saat keinginannya ditolak', 'Kepolosan hati, ketergantungan penuh pada orang tua, kerendahan hati, dan ketulusan tanpa kepura-puraan', 'Kelemahan fisik yang tidak bisa bekerja', 'Sifat yang suka berebut mainan'], 1, 'Yesus memuji kepolosan batin, kerendahan hati, dan kepercayaan murni anak-anak sebagai sikap rohani yang benar menyambut Allah.');
addQ(2, 'sulit', 'Rahmat Penghapusan Dosa Asal', 'Melalui Sakramen Baptis, seseorang dibebaskan dari dosa asal (peccatum originale). Apakah yang dimaksud dengan dosa asal?', ['Dosa memukul teman saat bermain pasir', 'Kondisi keterpisahan manusia dari Allah dan hilangnya rahmat kekudusan akibat ketidaktaatan manusia pertama (Adam dan Hawa)', 'Kesalahan tidak sengaja lupa mengerjakan PR', 'Dosa yang hanya dilakukan oleh orang lanjut usia'], 1, 'Dosa asal adalah luka keterpisahan kodrat manusia dari persekutuan dengan Allah yang dipulihkan oleh rahmat penebusan Kristus dalam baptisan.');
addQ(2, 'sulit', 'Misteri Keheningan Santo Yosef', 'Di dalam seluruh Kitab Suci Perjanjian Baru, tidak ada satu patah kata pun ucapan Santo Yosef yang tercatat. Pelajaran rohani terdalam dari keheningan Yosef adalah ...', ['Santo Yosef adalah seorang yang tidak bisa berbicara (bisu)', 'Iman sejati tidak diukur dari kefasihan berbicara atau banyak kata, melainkan dari ketaatan nyata, kesetiaan bertindak, dan keheningan mendengarkan kehendak Allah', 'Yosef takut berbicara di depan umum', 'Hanya kebetulan para penulis Injil lupa mencatatnya'], 1, 'Keheningan Yosef adalah keheningan kontemplatif yang penuh tindakan nyata ketaatan iman.');
addQ(2, 'sulit', 'Analisis Solidaritas Kawan si Lumpuh', 'Kisah empat kawan yang membongkar atap rumah di Kafarnaum demi menurunkan sahabatnya yang lumpuh ke depan kaki Yesus mengajarkan bahwa ...', ['Kita boleh merusak rumah orang lain kapan saja', 'Kasih persahabatan sejati menuntut pengorbanan, kerja sama tanpa putus asa, dan membawa sesama yang menderita kepada Kristus Sang Sumber Kesembuhan', 'Yesus hanya menyembuhkan orang yang memiliki empat kawan', 'Atap rumah di Galilea terbuat dari tanah liat yang murah'], 1, 'Iman yang hidup berbuah pada tindakan solidaritas nyata dan kegigihan membawa sesama kepada anugerah Kristus.');
addQ(2, 'sulit', 'Hakikat Doa Tobat Kesempurnaan Kasih', 'Mengapa dalam Doa Tobat kita diajarkan menyesal bukan terutama karena takut akan siksaan neraka, melainkan karena telah menghina Allah yang mahabaik?', ['Karena neraka itu tidak ada', 'Karena penyesalan sempurna bersumber dari cinta yang mendalam kepada Allah Sang Kebaikan Tertinggi, bukan sekadar ketakutan egois pada hukuman', 'Supaya doa tobat menjadi lebih cepat selesai dibaca', 'Hanya pilihan kata sastra liturgi'], 1, 'Penyesalan sempurna (contritio) digerakkan oleh kasih murni kepada Allah, melampaui ketakutan akan sanksi dosa (attritio).');
addQ(2, 'sulit', 'Makna Meterai Abadi Baptisan', 'Katekismus Gereja Katolik mengajarkan bahwa Sakramen Baptis hanya dapat diterima satu kali seumur hidup karena sakramen ini memeteraikan ...', ['Sertifikat kertas yang tidak bisa rusak', 'Karakter rohani tak terhapuskan (character indelebilis) yang menandai jiwa kita sebagai milik Kristus untuk selamanya', 'Nama lengkap di buku catatan sipil pemerintah', 'Janji untuk tidak boleh sakit seumur hidup'], 1, 'Baptisan mencetak meterai rohani abadi pada jiwa yang tidak dapat dihapus oleh dosa apa pun, sehingga tidak dapat diulang.');
addQ(2, 'sulit', 'Pemberian Terbesar Seorang Ayah Asuh', 'Meskipun Santo Yosef tahu bahwa bayi yang dikandung Maria berasal dari Roh Kudus dan bukan anak kandungnya, mengapa ia tetap setia mengambil Maria sebagai istrinya dan melindungi Yesus?', ['Karena Yosef dijanjikan imbalan emas oleh para imam bait Allah', 'Karena ketaatan imannya yang mutlak kepada firman Allah melalui malaikat dan kasih tulusnya menjaga kekudusan rencana keselamatan', 'Karena Yosef tidak memiliki sanak saudara lain di Nazaret', 'Karena takut diejek oleh tetangga kota Nazaret'], 1, 'Ketaatan iman Yosef melampaui logika duniawi; ia menjadi pelindung setia karya keselamatan Ilahi dengan keikhlasan total.');
addQ(2, 'sulit', 'Sikap Menghargai Benda-Benda Suci (Sakramentali)', 'Bagaimana sikap seorang anak katolik memperlakukan benda-benda suci seperti Salib, Rosario, patung kudus, dan air suci di rumah?', ['Memakainya untuk mainan perang-perangan di luar rumah', 'Menghormatinya dengan menyimpannya di tempat yang bersih dan pantas serta menggunakannya sebagai sarana doa mendekatkan diri kepada Allah', 'Membuangnya ke tempat sampah jika bosan', 'Menjualnya kepada teman kelas untuk jajan'], 1, 'Benda-benda sakramentali diberkati Gereja untuk menguduskan berbagai situasi hidup dan menuntun batin pada doa.');
addQ(2, 'sulit', 'Analisis Mukjizat di Kana: Kepekaan Bunda Maria', 'Di perkawinan Kana, Bunda Maria adalah orang pertama yang menyadari bahwa keluarga pengantin kehabisan anggur. Kepekaan Maria ini mengajarkan kita untuk ...', ['Suka mencampuri urusan dapur orang lain', 'Memiliki mata hati yang peka terhadap kesusahan dan kebutuhan sesama di sekitar kita serta membawanya dalam perantaraan doa kepada Yesus', 'Mengejek tuan rumah yang kurang menyediakan minuman', 'Pergi meninggalkan pesta perkawinan sebelum selesai'], 1, 'Bunda Maria adalah teladan kepekaan nurani ibu yang peduli pada kemaluan dan kebutuhan sesama serta menjadi pengantara syafaat.');
addQ(2, 'sulit', 'Menilai Integritas Mengembalikan Barang Teman', 'Bila kita meminjam pensil warna milik teman dan ada satu warna yang patah tanpa sengaja, tindakan yang berintegritas adalah ...', ['Menyembunyikan pensil yang patah di bawah meja guru', 'Meraut kembali pensil tersebut hingga runcing, mengembalikannya, dan berterus terang meminta maaf kepada pemiliknya', 'Menuduh teman lain yang mematahkannya', 'Mengembalikan dalam keadaan rusak sambil memarahi kawan'], 1, 'Tanggung jawab dan kejujuran memelihara kepercayaan serta menjaga kesucian relasi persahabatan.');
addQ(2, 'sulit', 'Filosofi Menyalakan Lilin Doa', 'Lilin doa yang ditaruh di depan altar atau patung Bunda Maria perlahan-lahan habis terbakar meleleh. Lelehan lilin tersebut menyimbolkan ...', ['Pemborosan minyak lilin yang sia-sia', 'Pengorbanan diri dan penyerahan seluruh hidup orang beriman yang rela habis tercurah dalam cinta kasih memuliakan Tuhan dan sesama', 'Cahaya listrik yang terlalu mahal', 'Tradisi membakar dupa suku gurun pasir'], 1, 'Lilin yang meleleh melambangkan pengorbanan kasih Kristus dan penyerahan jiwa umat yang rela habis demi kemuliaan Allah.');
addQ(2, 'sulit', 'Makna "Bapa Kami" Persaudaraan Universal', 'Ketika kita berdoa "Bapa Kami" (bukan "Bapaku sendiri"), kita diingatkan bahwa ...', ['Tuhan hanya menyukai orang yang memiliki saudara sekandung', 'Allah adalah Bapa bagi seluruh umat manusia, sehingga semua manusia di bumi adalah saudara-saudari kita yang wajib dikasihi dan dihormati', 'Kita tidak boleh berdoa sendirian di kamar tidur', 'Doa Bapa Kami hanya boleh diucapkan di gereja bersama-sama'], 1, 'Penyebutan "Bapa Kami" meruntuhkan egoisme pribadi dan menegaskan persaudaraan sejati seluruh umat manusia sebagai anak-anak dari satu Bapa.');
addQ(2, 'sulit', 'Pemberian Kasih Tanpa Pamrih Santo Antonius', 'Santo Antonius dari Padua terkenal sangat mengasihi orang-orang miskin sehingga di gereja sering ada kotak "Roti Santo Antonius". Tujuan kotak tersebut adalah ...', ['Membeli roti bakar untuk pastor paroki', 'Mengumpulkan derma sedekah umat guna membeli makanan bagi orang-orang telantar dan fakir miskin', 'Menyimpan sisa roti perayaan Misa', 'Pajak wajib bagi anak-anak sekolah'], 1, 'Roti Santo Antonius adalah wujud amal karitatif Gereja membela dan mencukupi pangan kaum papa.');
addQ(2, 'sulit', 'Etika Menerima Komuni Batin', 'Bagi anak-anak kelas 2 yang belum menerima Komuni Pertama, saat maju ke depan altar dalam Misa kudus sikap yang benar adalah ...', ['Merampas Hosti Kudus dari tangan pastor', 'Menyilangkan kedua tangan di depan dada dengan khidmat untuk menerima berkat dari imam', 'Menolak maju dan berlari keluar gereja', 'Meminta pastor memberikan anggur misa'], 1, 'Menyilangkan tangan di dada adalah tanda hormat memohon berkat rohani (komuni batin) sebelum saatnya menerima Komuni Pertama.');
addQ(2, 'sulit', 'Panggilan Menjaga Martabat Diri', 'Tubuh kita adalah bait kediaman Roh Kudus sejak dibaptis. Bagaimana anak kelas 2 menjaga martabat tubuhnya dari perbuatan tercela?', ['Membiarkan orang asing menyentuh bagian pribadi tubuh', 'Menjaga kesopanan berpakaian, menolak sentuhan yang tidak pantas dari siapa pun, dan berani melapor kepada orang tua atau guru jika merasa terancam', 'Mencoret-coret lengan dengan spidol tinta permanen', 'Menolak mandi dan berolahraga'], 1, 'Menjaga integritas tubuh adalah hak asasi anak dan kewajiban iman memuliakan bait Roh Kudus.');
addQ(2, 'sulit', 'Makna "Aku Percaya Akan Satu Roh Kudus"', 'Dalam Syadat Para Rasul kita menyatakan percaya kepada Roh Kudus. Karya Roh Kudus dalam hati seorang anak kecil dicontohkan dengan ...', ['Bisikan untuk berbuat jahat saat guru lengah', 'Suara hati nurani yang selalu mendorong kita memilih berbuat jujur, pemaaf, dan menolak perbuatan curang', 'Membuat anak bisa melompat tinggi melompati pagar', 'Membuat anak tidak perlu belajar saat ujian'], 1, 'Roh Kudus berkarya melalui suara hati nurani yang membimbing manusia kepada kebenaran dan kebajikan ilahi.');
addQ(2, 'sulit', 'Analisis Keteladanan Santo Tarsisius', 'Santo Tarsisius adalah seorang misdinar muda di Roma yang gugur sebagai martir dipukuli massa karena menolak menyerahkan Sakramen Mahakudus yang dibawanya. Nilai keteladanan Tarsisius adalah ...', ['Suka berkelahi di jalanan kota Roma', 'Kecintaan dan penghormatan yang luar biasa mendalam pada kesucian Tubuh Kristus serta kesetiaan memegang amanah iman', 'Kenekatan anak yang melarikan diri dari rumah', 'Menyimpan rahasia curian di balik baju'], 1, 'Santo Tarsisius adalah martir Ekaristi dan teladan utama para misdinar dalam menjaga kekudusan Sakramen Mahakudus.');
addQ(2, 'sulit', 'Menyikapi Sahabat yang Memiliki Cacat Fisik', 'Bagaimana seorang murid katolik mengamalkan cinta kasih Kristus kepada teman yang tuna rungu atau menggunakan kursi roda di sekolah?', ['Memperlakukannya dengan canggung atau menjauhinya', 'Menyambutnya dengan ramah, berkomunikasi dengan sabar, membantunya bergerak di sekolah, dan memperlakukannya setara penuh martabat', 'Menjadikan keterbatasan fisiknya sebagai lelucon kelas', 'Menatapnya dengan rasa kasihan yang merendahkan'], 1, 'Kasih sejati memandang sesama dengan tatapan martabat Allah, merangkul tanpa diskriminasi atau belas kasihan palsu.');
addQ(2, 'sulit', 'Pemberian Berkat Lewat Kata-kata', 'Yakobus 3:10 mengingatkan: "Dari mulut yang satu keluar berkat dan kutuk. Hal ini, saudara-saudaraku, tidak boleh demikian terjadi". Penerapan nasihat ini bagi anak kelas 2 adalah ...', ['Boleh memaki kawan saat jam istirahat saja', 'Menjaga lisan agar senantiasa mengeluarkan kata-kata yang membangun, menghibur, jujur, dan tidak mengucapkan perkataan kotor yang merendahkan orang lain', 'Hanya berbicara saat disuruh kepala sekolah', 'Berbisik-bisik membicarakan kekurangan guru'], 1, 'Lisan orang beriman dikuduskan untuk menabur berkat, kedamaian, dan kebenaran bagi sesama.');
addQ(2, 'sulit', 'Makna Lambang Merpati Roh Kudus', 'Roh Kudus sering dilambangkan dengan burung merpati putih seperti saat pembaptisan Yesus di Sungai Yordan. Lambang merpati ini mengajarkan sifat Roh Kudus yang ...', ['Ganas memangsa burung-burung kecil', 'Lembut, suci, membawa damai, dan menguduskan jiwa manusia', 'Suka bersarang di menara gereja', 'Mampu terbang sangat cepat di udara'], 1, 'Burung merpati menyimbolkan kelemahlembutan, kesucian, kedamaian, dan anugerah kasih ilahi.');
addQ(2, 'sulit', 'Kearifan Berbagi Ruang Bermain', 'Ketika lapangan bermain sekolah sempit dan banyak kelas ingin bermain bola, tindakan kelompok anak katolik yang bijaksana adalah ...', ['Mengusir adik kelas dengan ancaman kekerasan', 'Bermusyawarah membagi waktu bermain secara bergantian atau bermain bersama dengan gembira', 'Merusak bola kelas lain agar lapangan kosong', 'Mengadu kepada kepala sekolah sambil menangis'], 1, 'Berbagi fasilitas bersama secara adil dan musyawarah mencerminkan buah Roh kelemahlembutan dan keadilan.');
addQ(2, 'sulit', 'Analisis Doa Sebelum Belajar Santo Thomas Aquino', 'Santo Thomas Aquinas selalu berdoa sebelum belajar memohon terang Roh Kudus. Manfaat rohani dari berdoa sebelum menuntut ilmu adalah ...', ['Agar otak kita terisi ilmu pengetahuan tanpa perlu membaca buku', 'Menyadarkan bahwa akal budi manusia membutuhkan penerangan rahmat ilahi agar ilmu yang dipelajari digunakan untuk kebaikan dan kemuliaan Allah', 'Supaya bapak guru tidak memberi soal ujian yang rumit', 'Hanya formalitas tata tertib sekolah katolik'], 1, 'Ilmu pengetahuan tanpa terang iman dapat melahirkan kesombongan; doa menuntun akal budi pada hikmat sejati.');
addQ(2, 'sulit', 'Tantangan Menolak Sikap Manja', 'Bagaimana seorang anak katolik melatih kemandirian seturut teladan Keluarga Kudus Nazaret?', ['Menyuruh pembantu rumah tangga mengikatkan tali sepatu kita', 'Belajar menyiapkan buku pelajaran sendiri, merapikan mainan, dan membantu pekerjaan sederhana orang tua di rumah dengan sukacita', 'Menangis guling-guling jika permintaannya ditolak ibu', 'Menolak makan sayur di piring'], 1, 'Keluarga Kudus mendidik Yesus kecil dalam kesederhanaan, kemandirian, dan ketaatan bakti.');
addQ(2, 'sulit', 'Menilai Kebenaran di Atas Rasa Takut', 'Ketika kita melihat seorang kawan dituduh mencuri penghapus padahal pelakunya orang lain, tindakan moral yang benar adalah ...', ['Diam saja karena takut dimusuhi oleh pelaku sebenarnya', 'Berani bersuara jujur kepada guru dengan tenang bahwa teman yang dituduh tidak bersalah demi membela keadilan', 'Ikut menuduh agar masalah cepat selesai', 'Menertawakan teman yang sedang dituduh'], 1, 'Membela orang yang tidak bersalah adalah wujud keberanian moral menegakkan kebenaran kristiani.');
addQ(2, 'sulit', 'Makna "Damai Kristus Bersamamu"', 'Saat kita menyalami kawan dengan ucapan "Damai Kristus bersamamu", apa yang kita hadiahkan kepadanya?', ['Sekadar basa-basi seremonial Misa', 'Doa berkat agar damai sejahtera, pengampunan, dan sukacita yang berasal dari Kristus melingkupi hati dan hidupnya', 'Janji untuk mentraktirnya es krim sepulang gereja', 'Tanda bahwa kita siap bertanding sepak bola'], 1, 'Damai Kristus (Pax Christi) adalah anugerah keselamatan mendalam yang melampaui segala pengertian duniawi.');
addQ(2, 'sulit', 'Pemberian Terbesar Seorang Sahabat Sejati', 'Amsal 17:17 mengatakan seorang sahabat menaruh kasih setiap waktu dan menjadi saudara dalam kesukaran. Sikap sahabat sejati dicontohkan dengan ...', ['Meninggalkan kawan saat kawannya mendapat nilai jelek', 'Mendampingi, menghibur, dan membantu teman saat tertimpa duka, kesedihan, atau kesulitan belajar', 'Hanya mau berteman jika kawan membawa mainan baru', 'Membocorkan rahasia kawan di media sosial'], 1, 'Sahabat sejati teruji dalam masa kesukaran; kasihnya setia dan meneladani kesetiaan Kristus.');
addQ(2, 'sulit', 'Menjaga Kesucian Tempat Ibadah dari Sampah', 'Mengapa membuang bungkus permen atau menempelkan permen karet di bawah bangku gereja sangat dicela dalam ajaran Katolik?', ['Karena permen karet harganya murah', 'Karena mencemari dan menodai kesucian rumah Tuhan serta merugikan kenyamanan umat lain yang hendak berdoa dengan khidmat', 'Karena bangku gereja terbuat dari kayu jati mahal', 'Hanya aturan dari penjaga kebersihan gereja'], 1, 'Menjaga kebersihan dan kekudusan bait Allah mencerminkan penghormatan lahir batin kepada hadirat Ilahi.');
addQ(2, 'sulit', 'Kekuatan Pengampunan Dalam Persahabatan', 'Ketika dua orang sahabat bertengkar karena salah paham saat bermain balok lego, langkah terbaik seturut Injil adalah ...', ['Memutuskan pertemanan dan tidak saling menyapa selama satu tahun', 'Saling mendengarkan, meredakan ego pribadi, berani meminta maaf dan saling memaafkan sebelum hari berganti malam', 'Melaporkan masalah ke kantor polisi terdekat', 'Menghancurkan lego milik sahabat tersebut'], 1, 'Efesus 4:26 mengajarkan untuk tidak membiarkan amarah berlarut-larut; rekonsiliasi cepat memulihkan persaudaraan.');
addQ(2, 'sulit', 'Tantangan Menghadapi Tekanan Menyontek', 'Jika sahabat karib kita mengancam tidak mau berteman lagi jika kita tidak memberinya contekan saat ulangan, respons anak beriman adalah ...', ['Memberinya contekan demi menyelamatkan persahabatan', 'Menolak dengan santun dan menjelaskan bahwa persahabatan sejati tidak dibangun di atas kecurangan, serta menawarkan membantunya belajar bersama setelah ujian', 'Melaporkan dengan berteriak di ruang ujian', 'Memberikan jawaban yang sengaja disalahkan'], 1, 'Integritas sejati menolak kompromi dosa; persahabatan sejati justru saling menjaga dalam kebenaran dan kejujuran.');
addQ(2, 'sulit', 'Makna "Bapa yang Maharahim"', 'Gereja Katolik menyapa Allah sebagai "Bapa yang Maharahim". Makna maharahim (misericors) adalah ...', ['Allah yang suka menghukum manusia setiap kali bersalah', 'Allah yang berlimpah belas kasih, memiliki rahim cinta keibuan dan kebapaan yang tak terbatas menyayangi dan mengampuni anak-anak-Nya yang lemah', 'Allah yang tinggal sangat jauh di angkasa luar', 'Allah yang hanya menyayangi para imam dan suster'], 1, 'Kerahiman Allah (Divine Mercy) adalah puncak cinta kasih Allah yang selalu mengampuni dan merangkul orang berdosa yang bertobat.');

addQ(3, 'mudah', 'Dua Bagian Alkitab', 'Kitab Suci yang digunakan dalam Gereja Katolik terbagi menjadi dua bagian besar yaitu Perjanjian Lama dan ...', ['Perjanjian Baru', 'Perjanjian Sabat', 'Kisah Para Rasul', 'Surat-surat Paus'], 0, 'Kitab Suci terdiri dari Perjanjian Lama (46 kitab kanonik katolik) dan Perjanjian Baru (27 kitab).');
addQ(3, 'mudah', 'Dua Bagian Ekaristi', 'Perayaan Ekaristi (Misa Kudus) terdiri dari dua bagian pokok yaitu Liturgi Sabda dan ...', ['Liturgi Ekaristi', 'Liturgi Pakaian', 'Liturgi Kolekte', 'Liturgi Paduan Suara'], 0, 'Perayaan Misa Kudus berpusat pada dua meja: Meja Sabda (Liturgi Sabda) dan Meja Ekaristi (Liturgi Ekaristi).');
addQ(3, 'mudah', 'Hosti Kudus', 'Roti bulat putih tak beragi yang dikonsekrasi oleh imam menjadi Tubuh Kristus dalam Ekaristi dinamakan ...', ['Biskuit', 'Hosti', 'Roti gandum bakar', 'Kue bolu'], 1, 'Hosti berasal dari bahasa Latin hostia yang berarti kurban kurban penebusan.');
addQ(3, 'mudah', 'Masa Adven', 'Masa persiapan rohani selama empat minggu menyambut Hari Raya Natal kelahiran Tuhan Yesus dinamakan Masa ...', ['Adven', 'Prapaskah', 'Biasa', 'Paskah'], 0, 'Masa Adven (Adventus) adalah masa penantian gembira dan tobat menyambut kedatangan Kristus.');
addQ(3, 'mudah', 'Masa Prapaskah', 'Masa tobat, puasa, dan pantang selama 40 hari untuk mempersiapkan Hari Raya Paskah kebangkitan Kristus dinamakan Masa ...', ['Adven', 'Prapaskah', 'Natal', 'Pentakosta'], 1, 'Masa Prapaskah meneladani 40 hari Yesus berpuasa di padang gurun.');
addQ(3, 'mudah', 'Rabu Abu', 'Hari pertama pembukaan Masa Prapaskah di mana dahi umat Katolik ditandai dengan abu pertobatan adalah hari ...', ['Minggu Palma', 'Rabu Abu', 'Kamis Putih', 'Sabtu Suci'], 1, 'Rabu Abu menandai dimulainya 40 hari masa tobat dan puasa Gereja.');
addQ(3, 'mudah', 'Tabernakel', 'Kotak suci berharga di gereja tempat menyimpan Sakramen Mahakudus (Tubuh Kristus) dinamakan ...', ['Altar', 'Tabernakel', 'Ambo / Mimbar', 'Sakristi'], 1, 'Tabernakel adalah tempat penyimpanan bejana Ekaristi Mahakudus.');
addQ(3, 'mudah', 'Warna Liturgi Adven Prapaskah', 'Warna kain liturgi pada Masa Adven dan Masa Prapaskah yang melambangkan pertobatan dan penantian khidmat adalah warna ...', ['Merah', 'Ungu', 'Hijau', 'Putih'], 1, 'Warna ungu menyimbolkan tobat, keprihatinan, dan persiapan batin menyambut peristiwa agung.');
addQ(3, 'mudah', 'Warna Liturgi Paskah Natal', 'Warna busana liturgi imam pada Hari Raya Natal dan Paskah yang melambangkan kesucian, sukacita, dan kemuliaan adalah warna ...', ['Hitam', 'Putih atau Emas', 'Ungu', 'Hijau tua'], 1, 'Warna putih atau emas melambangkan kemuliaan, sukacita kebangkitan, dan cahaya kemenangan ilahi.');
addQ(3, 'mudah', 'Doa Angelus', 'Doa tradisional katolik yang didoakan tiga kali sehari (pukul 06.00, 12.00, dan 18.00) untuk mengenang peristiwa penjelmaan Yesus dinamakan Doa ...', ['Angelus (Doa Malaikat Tuhan)', 'Bapa Kami', 'Tobat', 'Pujian Sabat'], 0, 'Doa Malaikat Tuhan (Angelus) mengenang kabar sukacita Maria dan misteri Sabda menjadi manusia.');

addQ(3, 'sedang', 'Homili Imam', 'Dalam Liturgi Sabda, setelah pembacaan Kitab Suci, imam memberikan penjelasan dan renungan firman yang disebut ...', ['Kolekte', 'Homili (Khotbah)', 'Prefasi', 'Aklamasi'], 1, 'Homili bertujuan menguraikan sabda Allah dan mengaitkannya dengan kehidupan nyata sehari-hari.');
addQ(3, 'sedang', 'Sikap Mendengar Injil', 'Saat bacaan Injil hendak dibacakan oleh imam atau diakon dalam Misa kudus, seluruh umat mengambil sikap ...', ['Duduk bersila', 'Berdiri tegak dengan penuh hormat', 'Berlutut menundukkan kepala', 'Berjalan menuju sakristi'], 1, 'Berdiri tegak melambangkan kesiapan hati menyambut dan menghormati kehadiran Sabda Kristus.');
addQ(3, 'sedang', 'Tiga Tanda Salib Kecil Sebelum Injil', 'Sebelum mendengarkan Injil, umat membuat tiga tanda salib kecil dengan ibu jari pada dahi, mulut, dan dada dengan doa batin: ...', ['"Semoga aku cepat pulang ke rumah"', '"Semoga sabda Tuhan membersihkan pikiranku, terucap di bibirku, dan meresap di dalam hatiku"', '"Semoga lampu gereja tidak padam"', '"Semoga persembahan terkumpul banyak"'], 1, 'Tiga tanda salib kecil menandakan penyerahan pikiran, perkataan, dan hati kita agar dikuduskan oleh Injil.');
addQ(3, 'sedang', 'Arti Kata Ekaristi', 'Kata "Ekaristi" berasal dari kata bahasa Yunani "Eucharistia", yang memiliki arti harfiah ...', ['Pesta makan bersama', 'Mengucap syukur atau berterima kasih kepada Allah', 'Korban binatang persembahan', 'Rapat para rasul'], 1, 'Ekaristi adalah doa syukur agung atas seluruh karya penebusan Kristus.');
addQ(3, 'sedang', 'Perjamuan Terakhir Sabda Konsekrasi', 'Pada malam Perjamuan Terakhir sebelum wafat-Nya, Yesus mengambil roti, mengucap syukur, memecah-mecahkannya, lalu memberikannya kepada murid-murid-Nya sambil bersabda: ...', ['"Simpanlah roti ini di dalam lumbung"', '"Ambillah dan makanlah: Inilah Tubuh-Ku yang diserahkan bagimu"', '"Jualah roti ini ke pasar Yerusalem"', '"Roti ini hanya boleh dimakan para imam"'], 1, 'Lukas 22:19 merekam kata-kata penetapan Sakramen Ekaristi oleh Kristus sendiri.');
addQ(3, 'sedang', 'Empat Minggu Adven', 'Masa penantian Adven berlangsung selama ... minggu sebelum malam Natal.', ['2 minggu', '4 minggu', '6 minggu', '8 minggu'], 1, 'Masa Adven mencakup empat hari Minggu penantian kedatangan Kristus.');
addQ(3, 'sedang', 'Lilin Ketiga Adven Gaudete', 'Pada karangan Korona Adven, lilin ketiga berwarna merah muda (pink) yang dinyalakan pada Minggu Adven III dinamakan Minggu ...', ['Laetare', 'Gaudete (Minggu Sukacita)', 'Palma', 'Paskah'], 1, 'Gaudete berarti bersukacitalah, melambangkan sukacita karena kedatangan Sang Juruselamat sudah semakin dekat.');
addQ(3, 'sedang', 'Sabda Penaburan Abu', 'Saat imam mengoleskan abu pada dahi umat pada hari Rabu Abu, imam mengucapkan sabda pertobatan: ...', ['"Selamat hari raya Natal saudaraku"', '"Bertobatlah dan percayalah kepada Injil"', '"Ambillah persembahan ini sekarang"', '"Pergilah dalam damai Kristus"'], 1, 'Sabda penaburan abu mengajak umat memperbarui iman dan berbalik kepada Injil.');
addQ(3, 'sedang', 'Makna Puasa Katolik', 'Pantang dan puasa pada Masa Prapaskah bagi umat Katolik bertujuan untuk melatih penguasaan diri dan menyisihkan uang jajan untuk ...', ['Membeli pakaian pesta baru', 'Membantu kaum miskin, telantar, dan menderita (dana APP)', 'Membeli perhiasan emas gereja', 'Membayar denda tilang jalan raya'], 1, 'Puasa katolik berdimensi pertobatan batin dan solidaritas sosial karitatif membantu kaum dhuafa.');
addQ(3, 'sedang', 'Dana APP Prapaskah', 'Kotak amal berwarna ungu yang dibagikan ke rumah-rumah keluarga katolik selama Masa Prapaskah dinamakan kotak dana ...', ['Kolekte biasa', 'Aksi Puasa Pembangunan (APP)', 'Pajak paroki', 'Pesta natal bersama'], 1, 'Dana APP dihimpun dari hasil puasa dan pantang umat untuk mendanai karya sosial kemanusiaan.');
addQ(3, 'sedang', 'Mukjizat Kana Peran Maria', 'Ketika keluarga pengantin di Kana kehabisan anggur, Bunda Maria dengan penuh belas kasih menyampaikan kesulitan mereka kepada Yesus dengan berkata: ...', ['"Suruhlah semua tamu pulang sekarang juga"', '"Mereka kehabisan anggur"', '"Belilah anggur baru di kota tetangga"', '"Batalkan pesta pernikahan ini"'], 1, 'Yohanes 2:3: Maria menjadi pendoa syafaat pertama yang peka mempercayakan kebutuhan sesama kepada kuasa Yesus.');
addQ(3, 'sedang', 'Panggilan Samuel Kecil', 'Nabi Samuel saat masih belia dipanggil Tuhan di Kemah Suci Silo. Setelah dibimbing oleh Imam Eli, Samuel menjawab panggilan Tuhan dengan berkata: ...', ['"Jangan panggil aku, aku mau tidur"', '"Berbicaralah, TUHAN, sebab hamba-Mu ini mendengar"', '"Tanyakanlah kepada bapakku Elkana"', '"Aku tidak mengenal suara itu"'], 1, '1 Samuel 3:10: Kepatuhan Samuel mendengarkan firman menjadi teladan kesiapan jiwa menyambut panggilan Tuhan.');
addQ(3, 'sedang', 'Iman Tanpa Perbuatan Mati', 'Dalam Surat Yakobus 2:17 ditegaskan bahwa jika iman tidak disertai dengan perbuatan nyata cinta kasih, maka iman itu pada hakikatnya adalah ...', ['Sangat hebat', 'Mati', 'Akan dipuji para malaikat', 'Bisa menyelamatkan bangsa'], 1, 'Iman yang sejati membuahkan kebajikan konkret; iman tanpa perbuatan kasih adalah sia-sia dan mati.');
addQ(3, 'sedang', 'Inkulturasi Liturgi Gereja', 'Penggunaan alat musik gamelan, busana kebaya atau beskap, serta ornamen ukiran tradisional daerah dalam Misa kudus merupakan wujud dari ...', ['Penyembahan berhala kuno', 'Inkulturasi liturgi (menyatukan kekayaan budaya lokal dengan kekudusan iman katolik)', 'Pelanggaran hukum kanonik gereja', 'Pameran pariwisata daerah semata'], 1, 'Gereja Katolik menghargai budaya setempat; inkulturasi memperkaya ungkapan iman tanpa merusak ajaran pokok.');
addQ(3, 'sedang', 'Berdamai Sebelum Altar', 'Yesus bersabda dalam Matius 5:23-24: "Jika engkau mempersembahkan persembahanmu di atas mezbah dan teringat akan kesalahan saudaramu... pergilah berdamai dahulu dengan saudaramu, lalu ..."', ['Pulanglah dan jangan kembali ke gereja', 'Kembalilah mempersembahkan persembahanmu itu', 'Batalkan seluruh ibadahmu', 'Minta uang kompensasi ganti rugi'], 1, 'Matius 5:24: Rekonsiliasi damai dengan sesama adalah syarat utama agar ibadah persembahan kita berkenan di hadapan Allah.');
addQ(3, 'sedang', 'Simbol Evangelis Matius', 'Empat penulis Injil (Evangelis) memiliki lambang simbolis masing-masing. Santo Matius dilambangkan dengan ...', ['Singa bersayap', 'Manusia / Malaikat bersayap', 'Lembu jantan bersayap', 'Burung rajawali terbang'], 1, 'Injil Matius diawali dengan silsilah manusiawi Yesus Kristus sehingga dilambangkan dengan manusia bersayap.');
addQ(3, 'sedang', 'Simbol Evangelis Markus', 'Penulis Injil kedua, Santo Markus, dilambangkan dengan simbol hewan perkasa yaitu ...', ['Burung merpati', 'Singa bersayap', 'Rusa bertanduk emas', 'Ikan paus laut'], 1, 'Injil Markus diawali seruan Yohanes Pembaptis bagai suara singa mengaum di padang gurun.');
addQ(3, 'sedang', 'Simbol Evangelis Lukas', 'Penulis Injil ketiga, Santo Lukas, dilambangkan dengan simbol hewan kurban yaitu ...', ['Domba kecil', 'Lembu / Sapi jantan bersayap', 'Kuda putih', 'Ular perunggu'], 1, 'Injil Lukas diawali imam Zakharia mempersembahkan kurban di bait Allah sehingga dilambangkan lembu bersayap.');
addQ(3, 'sedang', 'Simbol Evangelis Yohanes', 'Penulis Injil keempat, Santo Yohanes, yang merenungkan ketinggian Sabda Ilahi yang menjadi manusia dilambangkan dengan ...', ['Kucing hutan', 'Burung Rajawali yang terbang membubung tinggi ke surga', 'Bintang berekor', 'Pohon zaitun'], 1, 'Injil Yohanes melambung tinggi dalam perenungan teologis Sabda Kekal laksana burung rajawali.');
addQ(3, 'sedang', 'Teladan Samaria Murah Hati', 'Perumpamaan Orang Samaria yang Murah Hati mengajarkan bahwa ukuran seorang sesama sejati adalah orang yang ...', ['Berasal dari suku yang sama dan kaya raya', 'Menunjukkan belas kasih nyata kepada siapa saja yang sedang tertimpa kemalangan tanpa memandang latar belakang', 'Memiliki jabatan imam tinggi di bait suci', 'Pandai berdebat tentang hukum agama'], 1, 'Sesamaku manusia adalah setiap insan yang memerlukan uluran belas kasih dan pertolongan kita.');

addQ(3, 'sulit', 'Doktrin Transubstansiasi Ekaristi', 'Gereja Katolik mengajarkan dogma "Transubstansiasi" dalam Perayaan Ekaristi. Apakah arti dari Transubstansiasi?', ['Roti dan anggur hanya berubah rasanya menjadi lebih manis', 'Perubahan seluruh hakikat substansi roti dan anggur menjadi Tubuh dan Darah sejati Kristus melalui doa konsekrasi dan kuasa Roh Kudus, meskipun rupa lahiriahnya (aksidensia) tetap tampak roti dan anggur', 'Hosti berubah menjadi daging berdarah secara fisik kasat mata', 'Roti gandum dibakar menjadi abu pertobatan'], 1, 'Transubstansiasi adalah misteri iman: substansi berubah total menjadi Tubuh dan Darah Kristus, sementara rupa luar (aksidensia) tetap rupa roti dan anggur.');
addQ(3, 'sulit', 'Analisis Teologis Peran Maria Pengantara di Kana', 'Mengapa tindakan Bunda Maria berkata kepada Yesus "Mereka kehabisan anggur" dan berkata kepada pelayan "Buatlah apa yang dikatakan-Nya" dipandang sebagai model perantaraan doa (syafaat) yang sempurna?', ['Karena Maria ingin mempercepat acara pesta', 'Karena Maria menghubungkan kebutuhan konkret penderitaan manusia kepada kuasa ilahi Kristus, sekaligus membimbing manusia untuk patuh mutlak melakukan kehendak firman Yesus', 'Karena Yesus menolak mendengarkan orang lain selain ibu-Nya', 'Supaya para pelayan memberi hadiah uang kepada Maria'], 1, 'Bunda Maria tidak menonjolkan diri; ia menjadi jembatan doa syafaat yang menghantar manusia pada kepatuhan kepada Kristus.');
addQ(3, 'sulit', 'Makna Masa Adven Berjaga-jaga', 'Mengapa bacaan Kitab Suci pada Minggu Adven pertama selalu menyerukan: "Berjaga-jagalah, sebab kamu tidak tahu pada hari mana Tuhanmu datang"?', ['Supaya umat Katolik tidak tidur semalaman selama empat minggu', 'Mendidik jiwa kita agar senantiasa siap sedia dalam kekudusan hidup, tidak terlelap dalam dosa kemalasan, menyongsong kedatangan Kristus baik di akhir zaman maupun dalam hidup harian', 'Peringatan akan terjadinya badai salju di musim dingin', 'Supaya kita cepat membeli pohon cemara Natal'], 1, 'Adven adalah masa kesiapsiagaan eskatologis: menyucikan hati agar layak menyambut kedatangan Kristus Sang Hakim Agung.');
addQ(3, 'sulit', 'Filosofi Abu di Dahi Rabu Abu', 'Abu yang dioleskan pada dahi umat pada hari Rabu Abu berasal dari pembakaran ...', ['Kertas koran bekas tahun lalu', 'Daun-daun palem yang telah diberkati pada perayaan Minggu Palma tahun sebelumnya', 'Kayu gaharu dari hutan rimba', 'Batu bara hitam'], 1, 'Daun palem Minggu Palma lambang kejayaan duniawi dibakar menjadi abu, mengingatkan betapa fananya kemuliaan dunia di hadapan keabadian Allah.');
addQ(3, 'sulit', 'Pemberian Silih (Satisfactio) Sakramen Tobat', 'Setelah seorang peniten mengaku dosa dan menerima absolusi dari imam dalam Sakramen Pengakuan Dosa, imam memberikan "penitensi" (denda dosa/silih). Tujuan pemberian silih tersebut adalah ...', ['Membayar upah pelayanan imam', 'Menyembuhkan luka rohani akibat dosa, memperbaiki kerugian yang ditimbulkan, dan melatih disiplin hidup baru yang lebih suci', 'Sebagai hukuman fisik agar merasa jera', 'Hanya formalitas administratif paroki'], 1, 'Penitensi/silih adalah langkah pemulihan dan reparasi moral atas dampak buruk dosa terhadap diri dan persekutuan Gereja.');
addQ(3, 'sulit', 'Teologi Liturgi Inkulturasi Konsili Vatikan II', 'Konsili Vatikan II dalam konstitusi Sacrosanctum Concilium menegaskan bahwa inkulturasi liturgis diperbolehkan selama ...', ['Tidak ada biaya tambahan dari keuskupan', 'Tidak mengubah hakikat kesatuan pokok ritus Romawi, mempertahankan kemurnian iman rasuli, dan selaras dengan martabat kekudusan rumah Allah', 'Seluruh bahasa liturgi diganti dengan dialek pasar', 'Imam boleh menari sesuka hati di atas altar'], 1, 'Inkulturasi liturgis yang sah memadukan nilai luhur budaya setempat dengan tetap menjaga kekudusan dan keutuhan misteri iman Gereja semesta.');
addQ(3, 'sulit', 'Analisis Panggilan Samuel: Ketaatan vs Kebisingan Dunia', 'Mengapa Samuel kecil membutuhkan bimbingan Imam Eli untuk menyadari bahwa suara yang memanggilnya di malam hari adalah suara Tuhan?', ['Karena suara Tuhan terlalu pelan untuk didengar', 'Karena seorang pemula membutuhkan pendamping rohani (bapa rohani) yang berpengalaman untuk membedakan roh (discretio spirituum) dan mengenali kehendak Tuhan di tengah keheningan batin', 'Karena Samuel sedang mengalami gangguan mimpi buruk', 'Karena bait Allah di Silo sangat berisik di waktu malam'], 1, 'Kisah Samuel menegaskan pentingnya bimbingan rohani (spiritual direction) dalam mengenali panggilan dan suara kebenaran Tuhan.');
addQ(3, 'sulit', 'Kritik Yakobus Iman Tanpa Perbuatan Bagi Pelajar', 'Bagaimana seorang siswa kelas 3 katolik menerapkan ajaran Santo Yakobus "Iman tanpa perbuatan adalah mati" saat di sekolah?', ['Hanya rajin membuat Tanda Salib di depan kelas tetapi suka menyontek dan mengejek kawan yang miskin', 'Membuktikan imannya melalui perbuatan nyata: belajar jujur, membantu teman yang kesulitan memahami pelajaran, dan ramah kepada semua orang', 'Menghafal seluruh nama paus tanpa pernah berdoa', 'Memakai kalung salib paling besar agar ditakuti kawan'], 1, 'Iman yang sejati memancar keluar dalam akhlak kebajikan nyata, integritas akademis, dan kasih pelayanan kepada sesama.');
addQ(3, 'sulit', 'Makna Lilin Merah Muda Adven (Gaudete)', 'Mengapa di tengah suasana warna ungu tobat masa Adven diselipkan satu lilin dan kasula imam berwarna merah muda pada Minggu Adven ke-3 (Gaudete)?', ['Karena pabrik lilin kehabisan pewarna ungu', 'Sebagai titik fajar sukacita di tengah masa tobat, menegaskan bahwa penantian panjang akan segera berakhir dan keselamatan fajar Natal sudah di ambang pintu', 'Merupakan warna kesukaan uskup agung', 'Hanya variasi hiasan agar tidak membosankan'], 1, 'Gaudete (bersukacitalah) adalah oase sukacita mesianik: menguatkan pengharapan umat bahwa kedatangan Sang Penebus sudah sangat dekat.');
addQ(3, 'sulit', 'Kaitan Paskah Yahudi dan Ekaristi Kristus', 'Yesus menetapkan Ekaristi Kudus pada malam perjamuan Paskah Yahudi. Dalam Ekaristi Perjanjian Baru, siapakah "Anak Domba Paskah" sejati yang dikurbankan untuk membebaskan manusia dari perbudakan dosa?', ['Seekor anak domba jantan berbulu putih mulia di Yerusalem', 'Tuhan Yesus Kristus sendiri yang mempersembahkan Tubuh dan Darah-Nya di kayu salib', 'Nabi Musa yang membelah Laut Merah', 'Para rasul di ruang atas Yerusalem'], 1, 'Yesus adalah Anak Domba Allah (Agnus Dei) sejati yang menghapus dosa dunia melalui kurban salib.');
addQ(3, 'sulit', 'Tantangan Menolak Dendam Tujuh Puluh Kali Tujuh Kali', 'Ketika Petrus bertanya apakah mengampuni saudara sampai tujuh kali sudah cukup, Yesus menjawab sampai "tujuh puluh kali tujuh kali". Makna hakiki ajaran Yesus ini adalah ...', ['Kita harus mencatat kesalahan teman sampai angka 490 kali baru boleh membalas memukul', 'Pengampunan orang beriman harus tanpa batas, tanpa syarat dendam, dan senantiasa membuka pintu rekonsiliasi seperti pengampunan Allah kepada kita', 'Kita hanya boleh mengampuni teman yang pintar matematika', 'Setelah 490 kali kita berhak menuntut ke pengadilan'], 1, 'Tujuh puluh kali tujuh adalah kiasan ketidakterbatasan: pengampunan sejati tidak menyimpan catatan dosa dan tidak berkesudahan.');
addQ(3, 'sulit', 'Makna "Ite Missa Est" Perutusan di Akhir Misa', 'Di akhir perayaan Ekaristi, imam berkata: "Marilah pergi, kita diutus" (Ite, missa est). Apakah panggilan hidup umat setelah mendengar perutusan tersebut?', ['Segera pulang ke rumah untuk tidur siang pulas', 'Membawa rahmat Kristus yang telah diterima di gereja untuk menjadi saksi kasih, damai, dan keadilan dalam pergaulan di sekolah dan masyarakat', 'Berbelanja makanan lezat di pusat perbelanjaan', 'Melupakan semua khotbah yang telah didengar'], 1, 'Missa est adalah perutusan apostolik: Ekaristi tidak berhenti di dalam gedung gereja, melainkan diwujudkan dalam aksi kasih nyata di tengah dunia.');
addQ(3, 'sulit', 'Analisis Makna Puasa Katolik: Mengapa Berpantang Makanan Tertentu?', 'Gereja Katolik mewajibkan pantang daging atau makanan yang disukai pada hari Jumat. Tujuan spiritual dari pantang tersebut adalah ...', ['Supaya peternak sapi tidak kehabisan stok daging', 'Melatih kehendak jiwa mengendalikan hawa nafsu kerakusan dan mempersembahkan mati raga kecil sebagai ungkapan syukur atas sengsara wafat Kristus pada hari Jumat', 'Supaya berat badan umat Katolik turun drastis', 'Hanya peraturan tradisi kuno di benua Eropa'], 1, 'Pantang adalah latihan asketis (mati raga) menundukkan keinginan daging demi menyelaraskan diri dengan kurban salib Kristus.');
addQ(3, 'sulit', 'Perbedaan Antara Dosa Ringan dan Dosa Berat', 'Katekismus Gereja Katolik membedakan antara dosa ringan (venial) dan dosa berat (mortal). Syarat suatu perbuatan menjadi dosa berat adalah perkara berat, dilakukan dengan ...', ['Tidak sengaja dan saat sedang mengantuk', 'Penuh kesadaran akal budi dan persetujuan kehendak bebas secara sengaja melawan hukum Allah', 'Paksaan dari orang lain dengan ancaman senjata', 'Kekhilafan anak-anak yang belum mengerti'], 1, 'Tiga syarat dosa berat: materi berat (materia gravis), kesadaran penuh (plena advertentia), dan persetujuan bebas yang disengaja (deliberatus consensus).');
addQ(3, 'sulit', 'Etika Mengikuti Misa Secara Sadar dan Aktif', 'Konsili Vatikan II menuntut umat berpartisipasi dalam liturgi secara "sadar, aktif, dan penuh penghayatan" (actuosa participatio). Contohnya bagi murid SD adalah ...', ['Hanya melamun atau tidur di bangku belakang', 'Ikut mendengarkan bacaan, menjawab aklamasi imam dengan lantang dan khidmat, serta bernyanyi dengan penuh sukacita', 'Bermain game di gawai tersembunyi di balik buku doa', 'Keluar masuk toilet gereja sepanjang perayaan Misa'], 1, 'Partisipasi aktif bukan sekadar hadir fisik, melainkan keterlibatan batin dan lahiriah yang utuh dalam menyembah Allah.');
addQ(3, 'sulit', 'Menilai Ketulusan Dalam Memberi Kolekte', 'Bila kita memasukkan uang kolekte ke dalam kantong persembahan Misa, motivasi batin yang benar menurut ajaran Santo Paulus adalah ...', ['Memberi dengan rasa terpaksa atau bersungut-sungut karena malu pada teman sebelah', 'Memberi dengan sukacita dan kerelaan hati sesuai kemampuan, sebab Allah mengasihi orang yang memberi dengan sukacita (2 Korintus 9:7)', 'Memamerkan uang lembaran merah paling baru agar dilihat orang banyak', 'Memasukkan kancing baju agar kantong persembahan berbunyi gemerincing'], 1, '2 Korintus 9:7: Allah mengasihi orang yang memberi dengan sukacita tanpa paksaan atau kepura-puraan.');
addQ(3, 'sulit', 'Makna Seruan "Agnus Dei" (Anak Domba Allah)', 'Sebelum komuni, umat melantunkan seruan "Anak Domba Allah, yang menghapus dosa dunia, kasihanilah kami / berilah kami damai". Doa ini diilhami oleh perkataan nabi ...', ['Nabi Elia di Gunung Karmel', 'Santo Yohanes Pembaptis saat menunjuk kepada Yesus di Sungai Yordan (Yohanes 1:29)', 'Nabi Yesaya di Yerusalem', 'Raja Daud di dalam istananya'], 1, 'Yohanes Pembaptis berseru: "Lihatlah Anak Domba Allah, yang menghapus dosa dunia!" saat Yesus datang dibaptis.');
addQ(3, 'sulit', 'Tantangan Menjaga Keheningan Batin Pasca Komuni', 'Setelah menerima Tubuh Kristus atau menerima berkat dan kembali ke bangku gereja, tradisi katolik mengajarkan saat hening pribadi (silent prayer) untuk ...', ['Mengobrol santai menanyakan kabar tetangga', 'Bersyukur dalam hati, menyembah, dan berdialog mesra dengan Kristus yang kini bersemayam di dalam jiwa kita', 'Melihat jam tangan menunggu kapan Misa selesai', 'Merapikan pakaian dan menyisir rambut'], 1, 'Keheningan pasca komuni adalah saat sakral perjumpaan pribadi paling intim antara jiwa beriman dengan Tuhan Yesus.');
addQ(3, 'sulit', 'Kearifan Sikap Terhadap Orang yang Menganiaya Gereja', 'Sejarah mencatat banyak orang kudus yang mengampuni para pembunuh mereka, seperti Paus Yohanes Paulus II yang mengunjungi dan memaafkan Mehmet Ali Agca di dalam sel penjara. Nilai luhur tindakan ini adalah ...', ['Mencari sensasi liputan berita internasional', 'Perwujudan nyata kasih pengampunan radikal Kristus yang melucuti dendam dan mengubah hati manusia yang keras dengan kekuatan belas kasih', 'Menghindari tuntutan hukum pemerintah Italia', 'Hanya formalitas seremonial jabatan Paus'], 1, 'Pemaafan Paus Yohanes Paulus II adalah teladan nyata kemuridan Kristus: mengalahkan kejahatan dengan kebaikan ilahi.');
addQ(3, 'sulit', 'Makna Korona Adven Lingkaran Daun Abadi', 'Korona Adven dibuat dalam bentuk lingkaran tanpa awal dan tanpa akhir dari dedaunan cemara hijau yang selalu segar. Bentuk lingkaran dan daun hijau ini melambangkan ...', ['Roda gerobak para petani Kanaan', 'Keabadian cinta kasih Allah yang tidak berkesudahan dan pengharapan hidup kekal yang tidak pernah layu di dalam Kristus', 'Hiasan pesta akhir tahun', 'Lambang bahwa bumi ini datar'], 1, 'Lingkaran melambangkan keabadian Allah tanpa awal dan akhir, dan warna hijau cemara menyimbolkan pengharapan hidup kekal.');
addQ(3, 'sulit', 'Tanggung Jawab Penatalayanan Lingkungan Anak Katolik', 'Ensiklik Paus Fransiskus Laudato Si\' mengingatkan kita bahwa bumi sedang menjerit karena luka kerusakan yang diakibatkan oleh keserakahan manusia. Tanggung jawab pelajar kelas 3 adalah ...', ['Menyalahkan negara-negara maju penghasil polusi tanpa berbuat apa-apa', 'Melakukan langkah nyata tobat ekologis: mematikan lampu yang tak terpakai, menanam pohon di pekarangan, menghemat air, dan tidak menggunakan kantong plastik sekali pakai', 'Membeli banyak mainan plastik baru setiap minggu', 'Membuang sampah baterai ke dalam sumur air'], 1, 'Pertobatan ekologis dimulai dari perubahan gaya hidup sederhana sehari-hari dalam merawat bumi rumah bersama.');
addQ(3, 'sulit', 'Analisis Makna Lilin Baptis Bagi Anak', 'Ketika lilin baptis diserahkan kepada orang tua dan bapa baptis dengan pesan "Jagalah terang ini agar tetap bernyala", apa arti rohani menjaga terang baptis tersebut?', ['Menjaga agar sumbu lilin tidak tertiup angin di dalam kamar', 'Mendidik anak dalam iman, membimbingnya hidup dalam kebenaran firman, dan menjaganya dari pengaruh kegelapan dosa hingga Kristus datang kembali', 'Menyimpan lilin di dalam kotak besi selamanya', 'Membeli korek api yang banyak di toko'], 1, 'Menjaga terang baptis berarti memelihara iman dan kekudusan hidup anak agar senantiasa bersinar di tengah dunia.');
addQ(3, 'sulit', 'Perlawanan Terhadap Sikap Mementingkan Diri Sendiri', 'Filipi 2:3-4 menasihatkan: "Dengan rendah hati anggaplah yang lain lebih utama dari pada dirimu sendiri; dan janganlah tiap-tiap orang hanya memperhatikan kepentingannya sendiri, tetapi ..."', ['Kekayaan harta orang lain yang bisa diambil', 'Kepentingan orang lain juga', 'Kelemahan dan kesalahan orang lain untuk diejek', 'Pemberian hadiah dari orang tua'], 1, 'Kerendahan hati kristiani menumbuhkan kepekaan altruistik: menaruh perhatian pada kebutuhan dan kesejahteraan sesama.');
addQ(3, 'sulit', 'Kearifan Berbahasa Santun di Rumah', 'Mengapa kata "tolong", "terima kasih", dan "maaf" sering disebut oleh Paus Fransiskus sebagai tiga kata kunci kebahagiaan dalam keluarga?', ['Karena ketiga kata tersebut berasal dari bahasa Latin kuno', 'Karena ketiga kata tersebut mencerminkan kerendahan hati, rasa hormat pada martabat orang lain, dan kerelaan mengakui keterbatasan diri', 'Supaya keluarga kita dipuji oleh bapak RT', 'Hanya peraturan tata krama jam makan malam'], 1, 'Tiga kata sederhana ini meruntuhkan keangkuhan ego dan memelihara keharmonisan serta kehangatan relasi keluarga.');
addQ(3, 'sulit', 'Makna "Sanctorum Communio" (Persekutuan Para Kudus)', 'Dalam Syahadat kita mengikrarkan percaya akan "Persekutuan Para Kudus". Arti dari persekutuan ini adalah ikatan rohani kasih antara ...', ['Hanya orang-orang suci yang sudah wafat ribuan tahun lalu', 'Gereja yang masih berziarah di bumi, jiwa-jiwa di api penyucian, dan para kudus yang telah bersukacita dalam kemuliaan surga di bawah satu Kepala yaitu Kristus', 'Para imam dan biarawati di seluruh dunia saja', 'Kelompok murid berprestasi di sekolah katolik'], 1, 'Persekutuan Para Kudus menghubungkan seluruh anggota tubuh mistik Kristus: Gereja peziarah (bumi), Gereja menderita (purgatorium), dan Gereja jaya (surga).');
addQ(3, 'sulit', 'Menyikapi Sahabat yang Sedang Berduka Cita', 'Bila ada sahabat sekelas kita yang baru saja kehilangan ayah tercintanya, teladan Yesus saat menangis di depan makam Lazarus (Yohanes 11:35) mengajarkan kita untuk ...', ['Melarang sahabat tersebut menangis karena menangis itu tanda tidak beriman', 'Hadir mendampingi dengan belas kasih tulus, ikut merasakan kedukaan hatinya, mendoakan arwah almarhum, dan memberi penguatan iman', 'Mengejek sahabat tersebut karena menjadi anak yatim', 'Menghindari sahabat tersebut agar tidak tertular kesedihan'], 1, 'Yesus menangis bersama orang yang berduka; empati kasih sejati merangkul sesama dalam penderitaan dan menghadiahkan penghiburan ilahi.');
addQ(3, 'sulit', 'Pemberian Pemaafan Tanpa Menuntut Ganti Rugi', 'Ketika seorang kawan yang tidak sengaja merobek buku tulis kita tidak memiliki uang untuk mengganti, tindakan kebajikan kristiani tertinggi yang dapat kita lakukan adalah ...', ['Menahan tas sekolah kawan tersebut sebagai jaminan', 'Memaafkannya dengan ikhlas, tidak menuntut ganti rugi yang memberatkannya, dan bersama-sama menempel kembali kertas yang robek', 'Menyuruh kawan tersebut menjadi pesuruh kita selama satu semester', 'Melaporkannya ke kantor polisi'], 1, 'Kemurahan hati yang membebaskan sesama dari beban berat mencerminkan keagungan belas kasih Allah Bapa.');
addQ(3, 'sulit', 'Makna Minyak Krisma Kudus', 'Minyak Krisma (Sanctum Chrisma) yang berbau harum semerbak digunakan dalam sakramen Baptis, Krisma, dan Imamat. Minyak harum ini melambangkan ...', ['Parfum untuk menyegarkan badan calon baptis', 'Pengurapan Roh Kudus yang menguduskan jiwa dan panggilan orang beriman untuk menyebarkan "keharuman Kristus" dalam perbuatan baik di tengah dunia', 'Minyak obat untuk menyembuhkan luka fisik', 'Tradisi mandi rempah raja-raja masa lampau'], 1, 'Minyak Krisma melambangkan pencurahan Roh Kudus yang memeteraikan orang beriman menjadi ksatria pembawa keharuman kebajikan Kristus.');
addQ(3, 'sulit', 'Tantangan Menjaga Kemurnian Niat Berdoa', 'Matius 6:5 memperingatkan agar saat berdoa jangan seperti orang munafik yang suka berdoa berdiri di tikungan jalan raya agar dilihat orang. Nasihat Yesus bagi kehidupan doa kita adalah ...', ['Tidak boleh berdoa sama sekali di tempat umum', 'Masuklah ke dalam kamarmu, tutuplah pintu, dan berdoalah kepada Bapamu yang ada di tempat tersembunyi dengan ketulusan hati yang murni tanpa mencari sanjungan manusia', 'Hanya boleh berdoa saat hari ulang tahun saja', 'Berdoa dengan menggunakan mikrofon pengeras suara'], 1, 'Kemurnian doa diukur dari ketulusan relasi intim hati dengan Bapa di surga, bukan dari panggung pencitraan pujian manusia.');
addQ(3, 'sulit', 'Mutiara Hikmat Santo Agustinus Hati yang Gelisah', 'Santo Agustinus merangkum kerinduan terdalam jiwa manusia dalam kalimat termasyhurnya: "Engkau telah menciptakan kami untuk diri-Mu, ya Tuhan, dan hati kami senantiasa gelisah, sebelum ..."', ['Mendapatkan piala penghargaan dari raja', 'Beristirahat di dalam Dikau', 'Memiliki rumah megah di tepi pantai', 'Memenangkan seluruh pertandingan olahraga'], 1, 'Hati manusia diciptakan untuk Allah; segala materi dan kesenangan fana dunia tidak akan pernah memuaskan dahaga jiwa selain persekutuan damai dengan Allah.');

